def enrich(text,papers):
 text['ru'].update(nav=['Главная','Исследования','Публикации','Биография','Контакты','Конференции'],bachelor='Бакалавриат · Нанотехнологии и микросистемная техника',awards='Награды и признание',count='Найдено работ:',present='сейчас')
 text['en']['nav'].append('Conferences');text['en']['bachelor']='BSc · Nanotechnology and Microsystem Engineering';text['en']['count']='Works found:'
 text['ru']['methodlist'][1]=('Структура и поверхность','Рентгеновская дифракция, карты обратного пространства, атомно-силовая микроскопия')
 for p,title in zip(papers,RU_TITLES):p['ru_title']=title
 for i,num in [(1,780),(3,695),(7,588)]:papers[i]['url']=f'http://en.rensit.ru/vypuski/article/{num}/'
 for i,num in [(4,61710),(6,61895),(8,58977)]:papers[i]['url']=f'http://journals.ioffe.ru/articles/viewPDF/{num}';papers[i]['pdf']=True
 papers[2]['url']='https://jmsn.press/publications/01-03005'
 for p in papers:p.setdefault('url','https://doi.org/'+p['doi'])

def paper(p,lang,text,a):
 ru=lang=='ru';t=text[lang]
 title=p['ru_title'] if ru else p['title']
 original=f'<p class="original-title" lang="en"><span lang="ru">Оригинальное название: </span>{esc(p["title"])}</p>' if ru else ''
 note=('<p class="pub-note">Опубликовано онлайн в 2026 году; выпуск журнала — январь 2027.</p>' if ru else '<p class="pub-note">Published online in 2026; journal issue: January 2027.</p>') if p['year']==2027 else ''
 authors=esc(p['authors']).replace('N. V. Dubitskiy','<strong>N. V. Dubitskiy</strong>').replace('N. Dubitskiy','<strong>N. Dubitskiy</strong>')
 label=('Читать PDF' if p.get('pdf') else 'Открыть статью') if ru else ('Read PDF' if p.get('pdf') else 'Read article')
 return f'''<article class="publication" data-year="{p['year']}"><div class="pub-year">{p['year']}<span>{t['conference'] if p.get('conference') else t['article']}</span></div><div><h3>{a(p['url'],esc(title))}</h3>{original}<p class="authors" lang="en">{authors}</p><p class="journal" lang="en"><em>{esc(p['journal'])}</em> · {p['details']}</p>{note}<div class="paper-links">{a(p['url'],label+' ↗')}<span class="doi">DOI: {p['doi']}</span>{a(p['preprint'],t['preprint']+' ↗') if p.get('preprint') else ''}</div></div></article>'''

def body(lang,page,text,papers,a,path,profiles):
 t=text[lang];ru=lang=='ru'
 def tr(r,e):return r if ru else e
