 def education():return f'''<div class="timeline-item"><span>2024–2026</span><div><h3>{t['master']}</h3><p>{t['hse']}</p>{a(THESIS,t['thesis']+' ↗')}</div></div><div class="timeline-item"><span>2020–2024</span><div><h3>{t['bachelor']}</h3><p>{t['mirea']}</p></div></div>'''
 def conferences(limit=None,year=None):
  rows=[]
