 def layout(content,toc):
  return f'''<div class="reading-layout"><aside class="contents"><nav aria-label="{tr('Содержание страницы','On this page')}"><p>{tr('Содержание','Contents')}</p>{''.join(a('#'+id,label) for id,label in toc)}</nav></aside><div class="article-body">{content}</div></div>'''
 bio=tr('Я изучаю, как устроены тонкие плёнки иридатов стронция и как через них проходит ток. Меня интересует связь между тем, что мы меняем при росте образца, и тем, что затем видим в измерениях. Почему одна подложка даёт металлический характер сопротивления, а другая меняет низкотемпературный отклик?','I study the structure of strontium iridate thin films and how electric current flows through them. I am interested in connecting what we change during growth to what we measure afterwards. Why does one substrate give a metallic resistance trend while another changes the low-temperature response?')
 if page=='home':
  hero=f'''<section class="hero" id="about" itemscope itemtype="https://schema.org/Person"><div class="hero-copy"><p class="eyebrow">{tr('Физик · ИРЭ РАН · Москва','Physicist · IRE RAS · Moscow')}</p><h1 itemprop="name">{t['name']}</h1><p class="other-name" itemprop="alternateName">{t['other']}</p><p class="hero-line">{tr('Как подложка меняет поведение электронов в тонкой плёнке?','How does a substrate change electron transport in a thin film?')}</p><p itemprop="description">{bio}</p><div class="actions">{a(path(lang,'research'),t['explore'],'button')}{a('mailto:'+EMAIL,tr('Написать мне ↗','Email me ↗'))}</div></div><aside class="profile-panel"><figure class="hero-portrait"><img itemprop="image" src="/assets/nikita-dubitskiy.jpg" width="1254" height="1254" alt="{t['name']} — {tr('физик','physicist')}" fetchpriority="high"></figure><dl class="profile-facts"><div><dt>{tr('Работа','Work')}</dt><dd>{lab()}</dd></div><div><dt>{tr('Материалы','Materials')}</dt><dd>SrIrO₃ · Sr₂IrO₄</dd></div><div><dt>{tr('Образование','Education')}</dt><dd>{tr('РТУ МИРЭА → НИУ ВШЭ','MIREA → HSE University')}</dd></div></dl><div class="profile-links">{''.join(a(v,k+' ↗') for k,v in list(profiles.items())[:3])}</div></aside></section>'''
  research=f'''<div class="research-intro"><div><h3>{tr('Один материал. Пять подложек.','One material. Five substrates.')}</h3><p>{tr('В магистерской работе я сравнил плёнки SrIrO₃ толщиной около 35 нм на пяти монокристаллических подложках. Измерения структуры, поверхности, химического состояния и сопротивления позволяют разбирать влияние подложки по отдельным признакам.','In my master’s thesis, I compared approximately 35 nm SrIrO₃ films on five single-crystal substrates. Structure, surface, chemical-state and resistance measurements help separate the different effects of the substrate.')}</p><p>{tr('Сопротивление измерялось от 4,2 до 300 К, эффект Холла — при 2 и 10 К в полях до ±7 Тл.','Resistance was measured from 4.2 to 300 K; the Hall effect at 2 and 10 K in fields up to ±7 T.')}</p>{a(path(lang,'research'),tr('Что показали измерения →','What the measurements show →'))}</div>{schematic()}</div>'''
  content=hero+section('research',tr('Исследования','Research'),research)+section('papers',t['selected'],''.join(paper(papers[i],lang,text,a) for i in [0,3,4])+a(path(lang,'publications'),t['allpapers']+' →'))+section('conferences',tr('Конференции','Conferences'),conferences(3)+a(path(lang,'conferences'),tr('Все конференции и доклады →','All conferences and contributions →')))+section('biography',t['education'],education())+section('recognition',tr('Обо мне в публикациях','Profile & recognition'),nto())+section('contact',tr('Связаться со мной','Get in touch'),'<p>'+tr('Обсудить плёнки, измерения или результаты статьи можно по почте. Если вопрос относится к конкретной работе, добавьте её название в тему письма.','Email me to discuss films, measurements or a paper. If your question concerns a particular study, include its title in the subject.')+'</p>'+contact_form())
  return layout(content,[('about',tr('Обо мне','About')),('research',t['nav'][1]),('papers',t['nav'][2]),('conferences',t['nav'][5]),('biography',t['education']),('recognition',tr('Факел НТО','Fakel NTO')),('contact',t['nav'][4])])
 heading=lambda title,intro:f'<header class="page-heading"><p class="eyebrow">{t["name"]}</p><h1>{title}</h1><p class="lead">{intro}</p></header>'
 if page=='research':
  topics=[('Подложка задаёт условия роста','The substrate sets the growth conditions', 'Я выращиваю оксидные плёнки методом ВЧ-магнетронного распыления. В серии SrIrO₃ меняется подложка, а вместе с ней — рассогласование решёток, деформация и морфология. Поэтому одинаковый химический состав ещё не означает одинаковое поведение образцов.','I grow oxide films by RF magnetron sputtering. In the SrIrO₃ series, changing the substrate changes lattice mismatch, strain and morphology. The same chemical formula does not mean the samples behave identically.'),('Структура, химия, затем транспорт','Structure, chemistry, then transport','Рентгеновская дифракция показывает ориентацию и параметры решётки. АСМ даёт рельеф поверхности. РФЭС помогает оценить химическое состояние иридия и кислородное окружение. Эти данные я сопоставляю с температурной зависимостью сопротивления и эффектом Холла.','X-ray diffraction gives the orientation and lattice parameters; AFM gives surface topography. XPS probes the Ir chemical state and oxygen environment. I compare these observations with resistance versus temperature and the Hall effect.'),('Что удалось увидеть','What the measurements show','В исследованной серии знак холловского отклика зависит от подложки. Для SrIrO₃ это важно: в проводимость могут вносить вклад и электроны, и дырки. На пьезоэлектрической PMN–PT напряжение до 300 В меняло сопротивление примерно на 0,022 % при комнатной температуре.','The Hall sign varies between substrates in the studied series. This matters in SrIrO₃ because both electrons and holes can contribute to conduction. On piezoelectric PMN–PT, a voltage of up to 300 V changed the room-temperature resistance by approximately 0.022%.'),('От отдельной плёнки к гетероструктуре','From a film to a heterostructure','Другое направление моей работы — иридаты стронция в сверхпроводящих гетероструктурах. Здесь интересен перенос тока через тонкую прослойку SrIrO₃ или Sr₂IrO₄ между электродами и роль сильного спин-орбитального взаимодействия.','Another part of my work concerns strontium iridates in superconducting heterostructures: current transport through a thin SrIrO₃ or Sr₂IrO₄ interlayer and the role of strong spin–orbit coupling.')]
  rows=''.join(f'<div class="research-row"><span>0{i+1}</span><div><h3>{tr(r,e)}</h3><p>{tr(br,be)}</p></div></div>' for i,(r,e,br,be) in enumerate(topics))
  content=heading(t['nav'][1],tr('От условий напыления к электронному транспорту.','From deposition conditions to electronic transport.'))+section('questions',tr('Что я исследую','Research questions'),rows+schematic())+section('atlas',tr('Научный атлас','Research atlas'),atlas())+section('methods',t['methods'],methods())+section('interpretation',tr('Где заканчиваются выводы','Limits of interpretation'),'<p>'+t['interpretation']+'</p>')+section('thesis',t['thesis'],thesis())+section('laboratory',tr('Лаборатория','Laboratory'),f'<p>{t["institute"]}</p><p>{lab()}</p><p>{tr("Физические основы функциональной тонкоплёночной оксидной электроники. Руководитель — Г. А. Овсянников.","Physical basis of functional thin-film oxide electronics. Head: G. A. Ovsyannikov.")}</p>')
  return layout(content,[('questions',tr('Задачи','Questions')),('atlas',tr('Научный атлас','Research atlas')),('methods',t['methods']),('interpretation',tr('Интерпретация','Interpretation')),('thesis',t['thesis']),('laboratory',tr('Лаборатория','Laboratory'))])
 if page=='publications':
  years=sorted({p['year'] for p in papers},reverse=True)
  intro=tr('Работы об оксидных плёнках, деформации решётки и переносе заряда. Для каждой статьи указана опубликованная версия; ранняя рукопись приведена рядом.','Papers on oxide films, lattice strain and charge transport. Each entry links to the published version, with earlier manuscripts alongside.')
  note=tr('Русские заголовки помогают ориентироваться в списке; оригинальные названия и библиографические данные приведены ниже.','Journal titles and bibliographic metadata follow the published versions.')
  return layout(heading(t['nav'][2],intro)+f'<p class="note">{note}</p><form class="filters" role="search"><div><label for="paper-search">{t["search"]}</label><input id="paper-search" type="search"></div><div><label for="paper-year">{t["year"]}</label><select id="paper-year"><option value="">{t["all"]}</option>{"".join(f"<option>{y}</option>" for y in years)}</select></div></form><p class="filter-status" role="status" aria-live="polite" data-label="{t["count"]}">{t["count"]} {len(papers)}</p><div id="papers">'+''.join(paper(p,lang,text,a) for p in papers)+f'</div><p id="no-results" hidden>{t["empty"]}</p>'+section('thesis',t['thesis'],thesis()),[('papers',tr('Статьи и тезисы','Articles & abstracts')),('thesis',t['thesis'])])
 if page=='conferences':
  intro=tr('Доклады и опубликованные материалы: от жидких кристаллов к оксидной электронике.','Talks and published proceedings: from liquid crystals to oxide electronics.')
  note=tr('Указана подтверждённая роль в каждой работе. Соавторство в материалах конференции само по себе не означает личного выступления.','Each entry states the documented contribution. Coauthorship of proceedings does not by itself establish an in-person presentation.')
  content=heading(t['nav'][5],intro)+f'<p class="note">{note}</p>'
  for y in ['2026','2025','2024','2023']:
   content+=section('year-'+y,y,conferences(year=y))
  return layout(content,[('year-'+y,y) for y in ['2026','2025','2024','2023']])
 if page=='cv':
  content=heading(t['nav'][3],tr('Никита Владимирович Дубицкий. Физик, инженер ИРЭ РАН.','Nikita Vladimirovich Dubitskiy. Physicist and research engineer at IRE RAS.'))+f'<button class="button print-button" type="button">{t["print"]}</button>'+section('experience',t['experience'],f'<div class="timeline-item"><span>2023 — {t["present"]}</span><div><h3>{t["engineer"]}</h3><p>{t["institute"]}</p><p>{lab()}</p><p>{t["work"]}</p></div></div>')+section('education',t['education'],education())+section('path',tr('Как я пришёл к этой теме','How I came to this topic'),'<p>'+tr('В МИРЭА я учился по направлению «Нанотехнологии и микросистемная техника». Первые конференционные работы были связаны с жидкими кристаллами и обнаружением микропластика. Затем я перешёл к оксидным плёнкам, рентгеновской дифракции и электронному транспорту. В магистратуре ВШЭ эта работа сложилась в исследование влияния подложки на SrIrO₃.','At MIREA, I studied Nanotechnology and Microsystem Engineering. My early conference work concerned liquid crystals and microplastic detection. I then moved to oxide films, X-ray diffraction and electronic transport. During my master’s degree at HSE University, this developed into a study of substrate effects in SrIrO₃.')+'</p>')+section('recognition',t['awards'],'<ul>'+''.join('<li>'+x+'</li>' for x in t['awardlist'])+'</ul>'+nto())+section('methods',t['methods'],methods())+section('conferences',t['nav'][5],'<p>'+a(path(lang,'conferences'),tr('Темы, даты и источники докладов →','Topics, dates and sources →'))+'</p>')
  return layout(content,[('experience',t['experience']),('education',t['education']),('path',tr('Путь в науку','Research path')),('recognition',t['awards']),('methods',t['methods']),('conferences',t['nav'][5])])
 content=heading(t['nav'][4],tr('Напишите, что вы исследуете и что хотите обсудить.','Tell me what you study and what you would like to discuss.'))+section('email',tr('Быстрое письмо','Quick email'),contact_form())+section('laboratory',tr('Место работы','Affiliation'),f'<p>{t["institute"]}</p><p>{lab()}</p><p>{t["location"]}</p>')+section('profiles',t['profiles'],'<ul class="contact-profiles">'+''.join('<li>'+a(v,k+' ↗')+'</li>' for k,v in profiles.items())+'</ul>')
 return layout(content,[('email',t['email']),('laboratory',tr('Лаборатория','Laboratory')),('profiles',t['profiles'])])
